import json


def normalize_expense(expense):
    normalized_expense = {
        "vendor": expense.get("vendor"),
        "date": expense.get("date"),
        "total": expense.get("total"),
        "items": [
            {"description": item.get("description"), "quantity": item.get("quantity"), "amount": item.get("amount")} for item in expense.get("line_items", [])
        ]
    }
    return json.dumps(normalized_expense, indent=2)

def validate_document_fields(document):
    required_fields = ["vendor", "date", "total"]
    for field in required_fields:
        if field not in document:
            return False
        if not document[field]:
            return False
    if "line_items" not in document or not document["line_items"]:
        return False
    for item in document["line_items"]:
        if "description" not in item or "quantity" not in item or "amount" not in item:
            return False
    return True

import os


def get_document_client(region):
    return boto3.client("textract", region_name=region)

class DocumentRequest:
    def __init__(self, document_bytes):
        self.document_bytes = document_bytes


class DocumentResponse:
    def __init__(self, response):
        self.response = response

def summarize_invoice_fields(invoice):
    summary = {
        "vendor": invoice.get("vendor"),
        "date": invoice.get("date"),
        "total": invoice.get("total"),
        "item_count": len(invoice.get("line_items", []))
    }
    return summary

import re


def moderate_vendor_text(text):
    if re.search(r"\b(fraud|scam|phishing)\b", text, re.IGNORECASE):
        return "Text contains sensitive content"
    return text

import boto3


def translate_invoice_note(note, target_language='es'):
    translate = boto3.client('translate')
    response = translate.translate_text(Text=note, SourceLanguageCode='en', TargetLanguageCode=target_language)
    return response.get('TranslatedText')
